// @ts-nocheck
import Component from 'flarum/common/Component';
/**
 * WsUpdateBanner — "N new discussions" pill shown when WebSocket events arrive.
 * Used by AllDiscussionsPage and TagPage.
 */
export default class WsUpdateBanner extends Component {
  view() {
    const {
      pendingCount,
      onFlush
    } = this.attrs;
    if (pendingCount <= 0) return null;
    const label = pendingCount === 1 ? '1 new discussion' : `${pendingCount} new discussions`;
    return m("div", {
      className: "AvocadoWsUpdate"
    }, m("button", {
      className: "AvocadoWsUpdate-btn",
      onclick: onFlush
    }, m("span", {
      className: "AvocadoWsUpdate-dot",
      "aria-hidden": "true"
    }), label));
  }
}
flarum.reg.add('ramon-avocado', 'forum/components/shared/WsUpdateBanner', WsUpdateBanner);